inputs.script:
// The links of the page the owner has open, as listing entries: same-site pages only, each once.
const norm = (raw) => { const u = new URL(raw); u.hash = ''; let t = u.toString(); if (u.pathname !== '/' && !u.search && t.endsWith('/')) t = t.slice(0, -1); return t; };
const host = location.hostname.replace(/^www\./, '');
const seen = new Set(); const items = [];
for (const a of document.querySelectorAll('a[href]')) {
  let url; try { url = new URL(a.getAttribute('href'), location.href); } catch (e) { continue; }
  if (!/^https?:$/.test(url.protocol) || url.hostname.replace(/^www\./, '') !== host) continue;
  const page = norm(url.toString()); if (seen.has(page)) continue; seen.add(page);
  const title = String(a.textContent || '').replace(/\s+/g, ' ').trim();
  const item = { type: 'rzn.item/v2', key: 'web:page:' + page, kind: 'page', url: page };
  if (title) item.title = title;
  items.push(item);
  if (items.length >= 500) break;
}
return { type: 'rzn.items/v2', listing: 'feed', next_cursor: null, items };
